import java.io.*;
import java.lang.reflect.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

/**
 * Differential behaviour test: original jar vs rebuilt jar.
 *
 * Two isolated class loaders. For every class present in both jars we pair methods
 * by *descriptor* (member names were regenerated by the deobfuscation, descriptors
 * were not), then call each pair with a fixed corpus of simple arguments and compare
 * either the returned value or the thrown exception class.
 *
 * Also runs a curated battery over the bundled org.json library (which kept its
 * names) with realistic JSON/XML/Cookie/HTTP inputs.
 */
public final class DiffTest {

    static ClassLoader orig, rebuilt;
    static final List<String> problems = new ArrayList<String>();
    static int compared, equal, skipped;

    public static void main(String[] a) throws Exception {
        File origJar = new File(a[0]);
        File newJar = new File(a[1]);
        File sdk = new File(a[2]);
        List<URL> libs = new ArrayList<URL>();
        for (int i = 3; i < a.length; i++) libs.add(new File(a[i]).toURI().toURL());
        orig = loader(origJar, sdk, libs);
        rebuilt = loader(newJar, sdk, libs);

        System.out.println("== curated org.json battery");
        jsonBattery();

        System.out.println("== curated VexView utility battery");
        vexBattery();

        System.out.println("== generic differential fuzz (static, simple signatures)");
        genericFuzz(origJar, newJar);

        System.out.println();
        System.out.println("compared=" + compared + " equal=" + equal + " skipped=" + skipped + " problems=" + problems.size());
        for (String p : problems) System.out.println("  !! " + p);
        if (!problems.isEmpty()) System.exit(1);
    }

    static ClassLoader loader(File jar, File sdk, List<URL> libs) throws Exception {
        List<URL> all = new ArrayList<URL>();
        all.add(jar.toURI().toURL());
        all.add(sdk.toURI().toURL());
        all.addAll(libs);
        return new URLClassLoader(all.toArray(new URL[0]), DiffTest.class.getClassLoader());
    }

    // ---------------------------------------------------------------- helpers
    static Object call(ClassLoader cl, String cls, String name, Class<?>[] types, Object... args) throws Throwable {
        Class<?> c = Class.forName(cls, true, cl);
        Method m = c.getDeclaredMethod(name, types);
        m.setAccessible(true);
        try {
            return m.invoke(null, args);
        } catch (InvocationTargetException e) {
            throw e.getTargetException();
        }
    }

    static void cmp(String label, Object x, Object y) {
        compared++;
        String sx = describe(x), sy = describe(y);
        if (sx.equals(sy)) {
            equal++;
        } else {
            problems.add(label + "\n      original: " + sx + "\n      rebuilt : " + sy);
        }
    }

    static String describe(Object o) {
        if (o == null) return "null";
        if (o instanceof Throwable) return "throw " + o.getClass().getName() + ": " + ((Throwable) o).getMessage();
        if (o instanceof Collection) {
            StringBuilder sb = new StringBuilder("[");
            for (Object e : (Collection<?>) o) sb.append(describe(e)).append(',');
            return sb.append(']').toString();
        }
        if (o instanceof Map) {
            List<String> parts = new ArrayList<String>();
            for (Map.Entry<?, ?> e : ((Map<?, ?>) o).entrySet()) parts.add(describe(e.getKey()) + "=" + describe(e.getValue()));
            Collections.sort(parts);
            return "{" + String.join(",", parts) + "}";
        }
        if (o.getClass().isArray()) {
            StringBuilder sb = new StringBuilder("(");
            for (int i = 0; i < Array.getLength(o); i++) sb.append(describe(Array.get(o, i))).append(',');
            return sb.append(')').toString();
        }
        String s = String.valueOf(o);
        return o.getClass().getSimpleName() + ":" + s;
    }

    static void both(String label, String cls, String name, Class<?>[] types, Object... args) {
        Object x = null, y = null;
        try { x = call(orig, cls, name, types, args); } catch (Throwable t) { x = t; }
        try { y = call(rebuilt, cls, name, types, args); } catch (Throwable t) { y = t; }
        cmp(label, x, y);
    }

    // ---------------------------------------------------------------- org.json
    static void jsonBattery() {
        final String[] inputs = {
            "{}",
            "{\"a\":1,\"b\":[1,2,3],\"c\":{\"d\":true,\"e\":null}}",
            "{\"name\":\"ve\\u0078view\",\"esc\":\"line\\nbreak\\ttab\\\"q\\\"\"}",
            "[1,2.5,\"three\",false,null,{\"k\":\"v\"}]",
            "{\"big\":123456789012345678,\"neg\":-0.0001,\"exp\":1.5e10}",
            "{\"dup\":1,\"dup\":2}",
            "{\"unicode\":\"中文 \\u00a7r\"}",
        };
        for (String in : inputs) {
            cmp("JSONObject(" + in + ") roundtrip", jsonToString(orig, in), jsonToString(rebuilt, in));
            cmp("JSONArray(" + in + ") roundtrip", arrayToString(orig, in), arrayToString(rebuilt, in));
        }

        // XML
        String xml = "<root a=\"1\"><child>x</child><child>y</child><empty/></root>";
        cmp("XML.toJSONObject", xmlToJson(orig, xml), xmlToJson(rebuilt, xml));
        cmp("XML.escape", staticCall(orig, "org.json.XML", "escape", new Class<?>[]{String.class}, "a<b>&\"'"),
                staticCall(rebuilt, "org.json.XML", "escape", new Class<?>[]{String.class}, "a<b>&\"'"));
        cmp("XML.unescape", staticCall(orig, "org.json.XML", "unescape", new Class<?>[]{String.class}, "&lt;a&gt;&amp;"),
                staticCall(rebuilt, "org.json.XML", "unescape", new Class<?>[]{String.class}, "&lt;a&gt;&amp;"));
        cmp("Cookie roundtrip", cookieRoundTrip(orig, "name=value; path=/; secure"), cookieRoundTrip(rebuilt, "name=value; path=/; secure"));
        cmp("HTTP.toJSONObject", httpParse(orig, "GET /index.html?x=1 HTTP/1.1\nHost: example.com\nAccept: */*\n\n"),
                httpParse(rebuilt, "GET /index.html?x=1 HTTP/1.1\nHost: example.com\nAccept: */*\n\n"));
        cmp("CDL.toJSONArray", cdlParse(orig, "a,b\n1,2\n3,4\n"), cdlParse(rebuilt, "a,b\n1,2\n3,4\n"));
        cmp("JSONTokener.nextValue", tokenerNext(orig, "{\"x\":[1,2,{\"y\":\"z\"}]}"), tokenerNext(rebuilt, "{\"x\":[1,2,{\"y\":\"z\"}]}"));
        cmp("JSONPointer", pointerGet(orig), pointerGet(rebuilt));
        cmp("JSONObject.quote", staticCall(orig, "org.json.JSONObject", "quote", new Class<?>[]{String.class}, "a\"b\\c\n"),
                staticCall(rebuilt, "org.json.JSONObject", "quote", new Class<?>[]{String.class}, "a\"b\\c\n"));
        cmp("JSONObject.doubleToString", staticCall(orig, "org.json.JSONObject", "doubleToString", new Class<?>[]{double.class}, 0.1),
                staticCall(rebuilt, "org.json.JSONObject", "doubleToString", new Class<?>[]{double.class}, 0.1));
        cmp("JSONObject.numberToString", staticCall(orig, "org.json.JSONObject", "numberToString", new Class<?>[]{Number.class}, 1.0E10),
                staticCall(rebuilt, "org.json.JSONObject", "numberToString", new Class<?>[]{Number.class}, 1.0E10));
    }

    static Object staticCall(ClassLoader cl, String cls, String name, Class<?>[] t, Object... args) {
        try { return call(cl, cls, name, t, args); } catch (Throwable e) { return e; }
    }
    static String jsonToString(ClassLoader cl, String in) {
        try {
            Class<?> c = Class.forName("org.json.JSONObject", true, cl);
            Constructor<?> ctor = c.getConstructor(String.class);
            Object o = ctor.newInstance(in);
            return String.valueOf(o);
        } catch (Throwable t) {
            Throwable e = t instanceof InvocationTargetException ? ((InvocationTargetException) t).getTargetException() : t;
            return "throw " + e.getClass().getName();
        }
    }

    static String arrayToString(ClassLoader cl, String in) {
        try {
            Class<?> c = Class.forName("org.json.JSONArray", true, cl);
            Constructor<?> ctor = c.getConstructor(String.class);
            Object o = ctor.newInstance(in);
            return String.valueOf(o);
        } catch (Throwable t) {
            Throwable e = t instanceof InvocationTargetException ? ((InvocationTargetException) t).getTargetException() : t;
            return "throw " + e.getClass().getName();
        }
    }

    static String xmlToJson(ClassLoader cl, String xml) {
        try {
            Class<?> c = Class.forName("org.json.XML", true, cl);
            Object o = c.getMethod("toJSONObject", String.class).invoke(null, xml);
            return String.valueOf(o);
        } catch (Throwable t) { return "throw " + t.getClass().getName(); }
    }

    static String cookieRoundTrip(ClassLoader cl, String s) {
        try {
            Class<?> c = Class.forName("org.json.Cookie", true, cl);
            Object o = c.getMethod("toJSONObject", String.class).invoke(null, s);
            return String.valueOf(o) + " -> " + c.getMethod("toString", Class.forName("org.json.JSONObject", true, cl)).invoke(null, o);
        } catch (Throwable t) { return "throw " + t.getClass().getName(); }
    }

    static String httpParse(ClassLoader cl, String s) {
        try {
            Class<?> c = Class.forName("org.json.HTTP", true, cl);
            return String.valueOf(c.getMethod("toJSONObject", String.class).invoke(null, s));
        } catch (Throwable t) { return "throw " + t.getClass().getName(); }
    }

    static String cdlParse(ClassLoader cl, String s) {
        try {
            Class<?> c = Class.forName("org.json.CDL", true, cl);
            Class<?> arr = Class.forName("org.json.JSONArray", true, cl);
            Object rows = arr.getConstructor(String.class).newInstance("[\"a\",\"b\"]");
            return String.valueOf(c.getMethod("toJSONArray", String.class, arr).invoke(null, s, rows));
        } catch (Throwable t) { return "throw " + t.getClass().getName(); }
    }

    static String tokenerNext(ClassLoader cl, String s) {
        try {
            Class<?> c = Class.forName("org.json.JSONTokener", true, cl);
            Object o = c.getConstructor(String.class).newInstance(s);
            Object v = c.getMethod("nextValue").invoke(o);
            return String.valueOf(v);
        } catch (Throwable t) { return "throw " + t.getClass().getName(); }
    }

    static String pointerGet(ClassLoader cl) {
        try {
            Class<?> p = Class.forName("org.json.JSONPointer", true, cl);
            Class<?> o = Class.forName("org.json.JSONObject", true, cl);
            Object json = o.getConstructor(String.class).newInstance("{\"a\":{\"b\":[10,20]}}");
            Object ptr = p.getConstructor(o, String.class).newInstance(json, "/a/b/1");
            return String.valueOf(p.getMethod("get").invoke(ptr));
        } catch (Throwable t) { return "throw " + t.getClass().getName(); }
    }

    // ---------------------------------------------------------------- VexView utils
    static void vexBattery() {
        // covered by the generic fuzz below; kept as a hook for future cases
    }
    // ---------------------------------------------------------------- generic fuzz
    static final Object[] ARGS_STR = {"", "abc", "a<b>c", "[local]x", "1,2,3", "<#>1<#&>2", "a\u00a7rb"};
    static final int[] ARGS_INT = {0, 1, -1, 7};
    static final double[] ARGS_DBL = {0.0, 1.5, -2.25};
    static final boolean[] ARGS_BOOL = {true, false};
    static final char[] ARGS_CHAR = {'a', '\n', ','};

    static void genericFuzz(File origJar, File newJar) {
        Map<String, String> map = classMap();
        List<String> cls = new ArrayList<String>();
        try {
            java.util.zip.ZipFile z = new java.util.zip.ZipFile(newJar);
            for (Enumeration<? extends java.util.zip.ZipEntry> en = z.entries(); en.hasMoreElements(); ) {
                String n = en.nextElement().getName();
                if (n.endsWith(".class") && n.startsWith("lk/")) cls.add(n.substring(0, n.length() - 6).replace('/', '.'));
            }
            z.close();
        } catch (Throwable t) { return; }

        for (String newName : cls) {
            String origName = reverseLookup(map, newName);
            Class<?> o, b;
            try { o = Class.forName(origName, false, orig); } catch (Throwable t) { continue; }
            try { b = Class.forName(newName, false, rebuilt); } catch (Throwable t) { continue; }
            for (Method om : o.getDeclaredMethods()) {
                if (!Modifier.isStatic(om.getModifiers()) || Modifier.isPrivate(om.getModifiers())) continue;
                if (om.getReturnType() == void.class) continue;
                if (!simpleParams(om.getParameterTypes())) continue;
                Method bm = findByDesc(b, argsDesc(om.getParameterTypes()), om.getReturnType());
                if (bm == null) continue;
                List<Object[]> tuples = tuplesFor(om.getParameterTypes());
                int n = 0;
                for (Object[] args : tuples) {
                    if (n++ > 6) break;
                    Object x, y;
                    try { om.setAccessible(true); bm.setAccessible(true); } catch (Throwable ignored) { }
                    try { x = om.invoke(null, args); } catch (Throwable t) { x = unwrap(t); }
                    try { y = bm.invoke(null, args); } catch (Throwable t) { y = unwrap(t); }
                    cmp(newName + "." + bm.getName() + "(" + join(args) + ")", x, y);
                }
            }
        }
    }

    static Object unwrap(Throwable t) {
        if (t instanceof InvocationTargetException) return ((InvocationTargetException) t).getTargetException();
        return t;
    }

    static String join(Object[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(a[i] instanceof String ? '"' + (String) a[i] + '"' : String.valueOf(a[i]));
        }
        return sb.toString();
    }

    static boolean simpleParams(Class<?>[] p) {
        for (Class<?> c : p) {
            if (c == String.class || c == int.class || c == long.class || c == double.class
                    || c == float.class || c == boolean.class || c == char.class || c == short.class || c == byte.class) continue;
            return false;
        }
        return p.length <= 3;
    }

    static List<Object[]> tuplesFor(Class<?>[] p) {
        List<Object[]> out = new ArrayList<Object[]>();
        out.add(defaults(p));
        // a few corpus variants
        for (int variant = 0; variant < 6; variant++) {
            Object[] args = new Object[p.length];
            for (int i = 0; i < p.length; i++) {
                Class<?> c = p[i];
                if (c == String.class) args[i] = ARGS_STR[variant % ARGS_STR.length];
                else if (c == int.class) args[i] = ARGS_INT[variant % ARGS_INT.length];
                else if (c == long.class) args[i] = (long) ARGS_INT[variant % ARGS_INT.length];
                else if (c == double.class) args[i] = ARGS_DBL[variant % ARGS_DBL.length];
                else if (c == float.class) args[i] = (float) ARGS_DBL[variant % ARGS_DBL.length];
                else if (c == boolean.class) args[i] = ARGS_BOOL[variant % ARGS_BOOL.length];
                else if (c == char.class) args[i] = ARGS_CHAR[variant % ARGS_CHAR.length];
                else if (c == short.class) args[i] = (short) 1;
                else if (c == byte.class) args[i] = (byte) 1;
            }
            out.add(args);
        }
        return out;
    }

    static Object[] defaults(Class<?>[] p) {
        Object[] a = new Object[p.length];
        for (int i = 0; i < p.length; i++) {
            Class<?> c = p[i];
            if (c == String.class) a[i] = "";
            else if (c == int.class) a[i] = 0;
            else if (c == long.class) a[i] = 0L;
            else if (c == double.class) a[i] = 0d;
            else if (c == float.class) a[i] = 0f;
            else if (c == boolean.class) a[i] = false;
            else if (c == char.class) a[i] = (char) 0;
            else if (c == short.class) a[i] = (short) 0;
            else if (c == byte.class) a[i] = (byte) 0;
        }
        return a;
    }

    static String argsDesc(Class<?>[] p) {
        StringBuilder sb = new StringBuilder("(");
        for (Class<?> c : p) sb.append(desc(c));
        return sb.append(')').toString();
    }

    static String desc(Class<?> c) {
        if (c == String.class) return "Ljava/lang/String;";
        if (c == int.class) return "I";
        if (c == long.class) return "J";
        if (c == double.class) return "D";
        if (c == float.class) return "F";
        if (c == boolean.class) return "Z";
        if (c == char.class) return "C";
        if (c == short.class) return "S";
        if (c == byte.class) return "B";
        return "?" + c.getName();
    }

    static Method findByDesc(Class<?> c, String paramsDesc, Class<?> ret) {
        Method only = null;
        int hits = 0;
        for (Method m : c.getDeclaredMethods()) {
            if (!Modifier.isStatic(m.getModifiers())) continue;
            if (m.getReturnType() != ret) continue;
            if (!argsDesc(m.getParameterTypes()).equals(paramsDesc)) continue;
            only = m;
            hits++;
        }
        if (hits != 1) return null;   // ambiguous (several methods share the signature)
        try { only.setAccessible(true); } catch (Throwable ignored) { }
        return only;
    }

static java.util.Map<String, String> classMap() {
        // final class name -> original (obfuscated) internal name
        java.util.Map<String, String> origOfObf = new java.util.HashMap<String, String>();
        java.util.Map<String, String> finalOfObf = new java.util.HashMap<String, String>();
        try {
            for (String line : java.nio.file.Files.readAllLines(new File("D:/deobf/vexview/work/classmap2.txt").toPath(), java.nio.charset.StandardCharsets.UTF_8)) {
                String[] p = line.trim().split("\\s+");
                if (p.length == 3 && "CLASS".equals(p[0])) origOfObf.put(p[2], p[1]);
            }
            for (String line : java.nio.file.Files.readAllLines(new File("D:/deobf/vexview/work/deobf.map").toPath(), java.nio.charset.StandardCharsets.UTF_8)) {
                String[] p = line.trim().split("\\s+");
                if (p.length == 3 && "CLASS".equals(p[0])) finalOfObf.put(p[1], p[2]);
            }
        } catch (Throwable t) { }
        java.util.Map<String, String> map = new java.util.HashMap<String, String>();
        for (java.util.Map.Entry<String, String> e : finalOfObf.entrySet()) {
            String orig = origOfObf.get(e.getKey());
            if (orig != null) map.put(e.getValue().replace('/', '.'), orig.replace('/', '.'));
        }
        return map;
    }

    static String reverseLookup(Map<String, String> m, String newName) {
        for (Map.Entry<String, String> e : m.entrySet()) if (e.getKey().equals(newName)) return e.getValue();
        return newName;
    }
}







